1	import { afterAll, beforeAll, describe, expect, it } from "vitest";
2	import { seaMap } from "@pirate-sea-race/content";
3	import { RubbingMessageType } from "@pirate-sea-race/protocol";
4	import { dockCentre, nearestDockBySea, startGameServer, type RunningGameServer } from "@pirate-sea-race/server";
5	import { createEncounterConfig } from "@pirate-sea-race/simulation/encounters";
6	import { cacheRubbings, objectiveRules } from "@pirate-sea-race/simulation/objectives";
7	import { AHEAD, HeadlessClient, ImpairmentProxy, sleep } from "@pirate-sea-race/test-tools";
8	import { GUEST_SEAT, holds, HOST_SEAT, lastDuel, ledgerOf, ledgerPlayer, pair, placePair, quickEncounters, tuned } from "./rubbingsSetup.js";
9	import { brawler, collectAt, containsText, dockFor, EAST, grapple, HOLD_E, HUB_X, OPEN_ROW, playersAt, roomOf, tracker, until, WEST } from "./seaDuelSetup.js";
10	
11	/**
12	 * Rubbings in the match room (§4, §11, §12, §16): collecting at an island's dock, stealing after a won duel at sea,
13	 * disconnects and quits through the ledger, claiming from a recovery cache, and what each client may see. Every test's
14	 * rooms check `checkLedger` and "no ship removed while the ledger counts its player" after every world tick
15	 * (`tracker`). The ledger keeps the rules' own timings here (six-second holds, the five-second theft window, the 60 s
16	 * seat); the encounter timings are shortened (`quickEncounters`). Expiries are in `rubbingsExpiry.test.ts`, Colyseus'
17	 * outer bound in `rubbingsOuterBound.test.ts`: one matchmaker per process means one set of timings per file.
18	 */
19	let server: RunningGameServer;
20	let endpoint: string;
21	const encounters = createEncounterConfig({ rules: quickEncounters });
22	
23	beforeAll(async () => {
24	  server = await startGameServer({ port: 0, host: "127.0.0.1", handleSignals: false, testPlacement: true, matchTuning: tuned({}) });
25	  endpoint = `http://127.0.0.1:${server.port}`;
26	});
27	
28	afterAll(async () => {
29	  await server.close();
30	});
31	
32	describe.concurrent("collecting at an island's dock (§4)", () => {
33	  it("collects the island's rubbing after six seconds of holding E, never a second of a type, and shows the island's types only while moored", async ({ onTestFinished }) => {
34	    const track = tracker(onTestFinished);
35	    const [player] = (await playersAt(endpoint, [HOST_SEAT], track)) as [HeadlessClient];
36	    const dock = dockFor("sun");
37	    await player.placeShip(endpoint, { tileX: dock.tileX, tileY: dock.tileY, heading: 0 });
38	    // On the dock's tile but not moored: the island's types are not the player's to see.
39	    await player.waitFor(() => player.objectives() !== undefined);
40	    expect(player.objectives()).toMatchObject({ gold: 50, rubbings: [], islandTypes: [], target: "", channel: "" });
41	
42	    // One gesture: E moors, and the same hold collects the island's first Sun.
43	    let startTick = -1;
44	    const seen = { islandTypes: new Set<string>(), targets: new Set<string>(), totals: new Set<number>() };
45	    await player.holdUntil(
46	      HOLD_E,
47	      () => {
48	        const channel = ledgerPlayer(player)?.channel;
49	        if (channel != null) startTick = channel.startTick;
50	        const status = player.objectives()!;
51	        seen.islandTypes.add(status.islandTypes.join(","));
52	        seen.targets.add(status.target);
53	        if (status.channel !== "") seen.totals.add(status.channelTotal);
54	        return player.rubbings().includes("sun");
55	      },
56	      12_000,
57	    );
58	    const status = player.objectives()!;
59	    expect(status.channelResult).toBe("collected:sun");
60	    // Exactly the rule's six seconds (120 world ticks) of holding, from the tick the hold started.
61	    expect(objectiveRules.collectTicks).toBe(120);
62	    expect(status.channelResultAt - startTick).toBe(objectiveRules.collectTicks);
63	    expect(seen.islandTypes).toContain("sun,sun");
64	    expect(seen.targets).toContain("collect:sun");
65	    expect([...seen.totals]).toEqual([120]);
66	    expect(player.ship()?.dock).toBe(dock.id);
67	
68	    // Holding on collects nothing more: the island's other Sun stays sealed, and E has no target here.
69	    await player.hold(HOLD_E, 1500);
70	    expect(holds(player, player.sessionId)).toEqual(["sun"]);
71	    expect(player.objectives()).toMatchObject({ rubbings: ["sun"], islandTypes: ["sun"], target: "", channel: "" });
72	    expect(ledgerOf(player).rubbings.filter((rubbing) => rubbing.location.kind === "player")).toHaveLength(1);
73	
74	    // Cast off: at sea the island's types are gone from the HUD again.
75	    await player.holdUntil(AHEAD, () => player.ship()?.dock === -1, 3000);
76	    await player.waitFor(() => player.objectives()!.islandTypes.length === 0);
77	  }, 30_000);
78	
79	  it("resets the hold when E is released or the ship casts off, and starts again from zero", async ({ onTestFinished }) => {
80	    const track = tracker(onTestFinished);
81	    const [player] = (await playersAt(endpoint, [HOST_SEAT], track)) as [HeadlessClient];
82	    const dock = dockFor("moon");
83	    await player.placeShip(endpoint, { tileX: dock.tileX, tileY: dock.tileY, heading: 0 });
84	    await player.hold(HOLD_E, 1500);
85	    const first = ledgerPlayer(player)?.channel;
86	    // Released: the ledger drops the hold and its progress.
87	    await until(() => ledgerPlayer(player)?.channel === null, 2000, "the released hold cancelled");
88	    expect(player.rubbings()).toEqual([]);
89	    await player.waitFor(() => player.objectives()!.channel === "" && player.objectives()!.channelHeld === 0);
90	
91	    // Holding again counts from zero, from a later tick.
92	    await player.holdUntil(HOLD_E, () => (ledgerPlayer(player)?.channel?.heldTicks ?? 0) >= 10, 3000);
93	    const second = ledgerPlayer(player)?.channel ?? null;
94	    expect(second).not.toBeNull();
95	    if (first !== undefined && first !== null) expect(second!.startTick).toBeGreaterThan(first.startTick);
96	    // Casting off (E let go, throttle ahead) ends it too; the ship is back at sea with nothing collected.
97	    await player.holdUntil(AHEAD, () => player.ship()?.dock === -1, 3000);
98	    await until(() => ledgerPlayer(player)?.channel === null, 2000, "the hold cancelled on casting off");
99	    expect(player.rubbings()).toEqual([]);
100	    expect(player.objectives()!.channelResult).toBe("");
101	  }, 30_000);
102	
103	  it("resets the hold when a grapple reserves the collector for a duel", async ({ onTestFinished }) => {
104	    const track = tracker(onTestFinished);
105	    const dock = dockFor("sun");
106	    // The collector at Palm Key's west dock; the attacker five tiles west of it on open water, facing it.
107	    const [collector, attacker] = (await playersAt(
108	      endpoint,
109	      [
110	        { tileX: dock.tileX, tileY: dock.tileY, heading: 0 },
111	        { tileX: dock.tileX - 5, tileY: dock.tileY, heading: EAST },
112	      ],
113	      track,
114	    )) as [HeadlessClient, HeadlessClient];
115	    const holding = collector.holdUntil(HOLD_E, () => collector.status()?.mode === "duel", 8000);
116	    await until(() => (ledgerPlayer(collector)?.channel?.heldTicks ?? 0) >= 20, 4000, "the collection under way");
117	    attacker.tapGrapple();
118	    await holding;
119	    // The reservation cancelled the hold: nothing collected, no hold left, the ledger holds the duel.
120	    expect(ledgerPlayer(collector)?.channel).toBeNull();
121	    expect(collector.rubbings()).toEqual([]);
122	    expect(lastDuel(collector)).toMatchObject({ phase: "fighting", players: [attacker.sessionId, collector.sessionId] });
123	    expect(ledgerOf(collector).rubbings.every((rubbing) => rubbing.location.kind === "source")).toBe(true);
124	  }, 30_000);
125	});
126	
127	describe.concurrent("disconnects in the world (§12)", () => {
128	  it("resets a hold on a disconnect, and a reconnect within the seat's reservation resumes the same player, ship and rubbings", async ({ onTestFinished }) => {
129	    const track = tracker(onTestFinished);
130	    const proxy = await ImpairmentProxy.start(server.port);
131	    onTestFinished(async () => void (await proxy.close()));
132	    const [player] = (await playersAt(endpoint, [HOST_SEAT], track, { endpoints: [proxy.endpoint] })) as [HeadlessClient];
133	    // A Sun first (six seconds: the SDK reconnects only a room joined five seconds ago).
134	    await collectAt(player, endpoint, dockFor("sun"), "sun");
135	    const dock = dockFor("moon");
136	    await player.placeShip(endpoint, { tileX: dock.tileX, tileY: dock.tileY, heading: 0 });
137	    const holding = player.hold(HOLD_E, 1500);
138	    await until(() => (ledgerPlayer(player)?.channel?.heldTicks ?? 0) >= 10, 3000, "the Moon hold under way");
139	    proxy.sever({ refuse: true });
140	    await holding;
141	    // The ledger has the player disconnected at once, hold cancelled, seat reserved for 60 s; the ship stays moored.
142	    await until(() => ledgerPlayer(player)?.status === "disconnected", 3000, "the disconnect");
143	    const away = ledgerPlayer(player)!;
144	    expect(away.channel).toBeNull();
145	    expect(away.reservationDeadline! - roomOf(player).matchState.worldTick).toBeGreaterThan(objectiveRules.seatReservationTicks - 40);
146	    expect(roomOf(player).matchState.ships.find((ship) => ship.id === player.sessionId)?.dock).toBe(dock.id);
147	    await sleep(500);
148	    proxy.restore();
149	    await player.waitFor(() => player.connected && ledgerPlayer(player)?.status === "connected", 10_000);
150	    // The same player: same id, rubbings and gold; the hold starts again from zero.
151	    expect(holds(player, player.sessionId)).toEqual(["sun"]);
152	    expect(player.objectives()).toMatchObject({ gold: 50, rubbings: ["sun"] });
153	    const back = roomOf(player).matchState.worldTick;
154	    await player.holdUntil(HOLD_E, () => player.rubbings().includes("moon"), 10_000);
155	    expect(player.objectives()!.channelResultAt - back).toBeGreaterThanOrEqual(objectiveRules.collectTicks);
156	  }, 45_000);
157	
158	
159	  it("puts a quitter's rubbings in a cache at the dock nearest by sea, a marker seen only within sight, whose contents only a player moored there sees", async ({ onTestFinished }) => {
160	    const track = tracker(onTestFinished);
161	    const east = seaMap.docks[1]!;
162	    expect(east).toMatchObject({ tileX: 93, tileY: 21 });
163	    // The quitter four tiles east of Ember Rock's east dock; a near watcher in its sight; a far one out of it.
164	    const [quitter, near, far] = (await playersAt(
165	      endpoint,
166	      [
167	        { tileX: 97, tileY: 21, heading: EAST },
168	        { tileX: 99, tileY: 26, heading: WEST },
169	        { ...HOST_SEAT },
170	      ],
171	      track,
172	    )) as [HeadlessClient, HeadlessClient, HeadlessClient];
173	    await collectAt(quitter, endpoint, dockFor("sun"), "sun");
174	    await quitter.placeShip(endpoint, { tileX: 97, tileY: 21, heading: EAST });
175	    const marks = { near: near.frameCount, far: far.frameCount };
176	    const quitTick = roomOf(near).matchState.worldTick;
177	    await quitter.leave();
178	    await near.waitFor(() => near.caches().length === 1, 3000);
179	    // The cache is at the dock nearest the quitter by sea, holding exactly the Sun, and the ship is gone.
180	    expect(nearestDockBySea(seaMap, (97 * 256) + 128, (21 * 256) + 128)).toBe(east.id);
181	    const [marker] = near.caches();
182	    expect(marker).toMatchObject({ ...dockCentre(seaMap, east.id), dock: east.id });
183	    const ledger = ledgerOf(near);
184	    expect(ledger.caches[0]!.createdTick - quitTick).toBeLessThanOrEqual(2);
185	    expect(cacheRubbings(ledger, ledger.caches[0]!.id).map((rubbing) => rubbing.type)).toEqual(["sun"]);
186	    expect(near.ship(quitter.sessionId)).toBeUndefined();
187	    expect(near.playerCount).toBe(2);
188	    // Out of sight, no marker; the marker carries no contents, and nobody at sea got them.
189	    await sleep(300);
190	    expect(far.caches()).toEqual([]);
191	    for (const [name, client] of [["near", near], ["far", far]] as const) {
192	      expect(client.framesSince(marks[name]).some((frame) => containsText(frame, "sun")), name).toBe(false);
193	    }
194	    // A player moored at that dock who holds every type in the cache sees the contents but cannot claim: E has no target.
195	    await collectAt(near, endpoint, dockFor("sun", 1), "sun");
196	    await near.placeShip(endpoint, { tileX: east.tileX, tileY: east.tileY, heading: 0 });
197	    await near.hold(HOLD_E, 1200);
198	    expect(near.ship()?.dock).toBe(east.id);
199	    expect(near.objectives()).toMatchObject({ cacheTypes: ["sun"], islandTypes: ["moon", "moon"], target: "collect:moon" });
200	    // It collects the island's Moon first (sources before caches), then has nothing left to do here.
201	    await near.holdUntil(HOLD_E, () => near.rubbings().includes("moon"), 10_000);
202	    await near.hold(HOLD_E, 1200);
203	    expect(near.objectives()).toMatchObject({ rubbings: ["sun", "moon"], cacheTypes: ["sun"], target: "", channel: "" });
204	    expect(ledgerOf(near).caches).toHaveLength(1);
205	  }, 45_000);
206	
207	});
208	
209	describe.concurrent("theft after a duel at sea (§4, §11)", () => {
210	  it("offers the winner the loser's type for five seconds, takes the chosen one with the gold, and returns the players only then", async ({ onTestFinished }) => {
211	    const track = tracker(onTestFinished);
212	    const { host, guest } = await pair(endpoint, track);
213	    await Promise.all([collectAt(host, endpoint, dockFor("sun"), "sun"), collectAt(guest, endpoint, dockFor("moon"), "moon")]);
214	    await placePair(endpoint, host, guest);
215	    await grapple(host, guest);
216	    host.fighter.play(brawler(0));
217	    await host.waitFor(() => (host.objectives()?.theftOptions.length ?? 0) > 0, 25_000);
218	    // Only the winner has the choice: the Moon, for the theft window.
219	    const duel = lastDuel(host)!;
220	    expect(duel).toMatchObject({ phase: "choosing", result: { outcome: "win", winner: host.sessionId, loser: guest.sessionId } });
221	    expect(duel.choiceDeadline! - duel.result!.tick).toBe(objectiveRules.theftChoiceTicks);
222	    expect(host.objectives()).toMatchObject({ theftOptions: ["moon"], theftDeadline: duel.choiceDeadline });
223	    expect(guest.objectives()).toMatchObject({ theftOptions: [], theftDuel: "" });
224	    // Nobody returns before the settlement: both still in the duel, the fight ended in the rules.
225	    await sleep(500);
226	    for (const client of [host, guest]) expect(client.status()?.mode).toBe("duel");
227	    expect(roomOf(host).encounterState.duels[0]).toMatchObject({ phase: "ended" });
228	    // The loser cannot choose, nor can a malformed choice do anything.
229	    const key = host.objectives()!.theftDuel;
230	    guest.chooseTheft("moon", key);
231	    host.chooseTheft("tide", key);
232	    host.sendRaw(RubbingMessageType.ChooseTheft, { duel: key, type: "moon", extra: 1 });
233	    await sleep(300);
234	    expect(lastDuel(host)?.phase).toBe("choosing");
235	    host.chooseTheft("moon");
236	    await host.waitFor(() => host.rubbings().join(",") === "sun,moon", 2000);
237	    expect(lastDuel(host)?.settlement).toMatchObject({ choice: "winner", stolenType: "moon", gold: 10, goldSuppressed: false });
238	    await guest.waitFor(() => guest.objectives()!.settledRole === "loser");
239	    expect(host.objectives()).toMatchObject({ gold: 60, settledRole: "winner", stolen: "moon", goldChange: 10 });
240	    expect(guest.objectives()).toMatchObject({ gold: 40, rubbings: [], settledRole: "loser", stolen: "moon", goldChange: -10 });
241	    // Then, and only then, the return: the winner protected at sea, the loser waiting to respawn.
242	    await host.waitFor(() => host.status()?.protection === "win", 2000);
243	    await guest.waitFor(() => guest.status()?.mode === "respawning", 2000);
244	    expect(host.status()!.protectedUntil).toBe(lastDuel(host)!.settlement!.tick + encounters.winProtectionTicks);
245	  }, 45_000);
246	
247	  it("applies the default theft at the deadline when the winner does not choose", async ({ onTestFinished }) => {
248	    const track = tracker(onTestFinished);
249	    const { host, guest } = await pair(endpoint, track, { autoReady: false });
250	    await Promise.all([collectAt(host, endpoint, dockFor("sun"), "sun"), collectAt(guest, endpoint, dockFor("moon"), "moon")]);
251	    await placePair(endpoint, host, guest);
252	    await grapple(host, guest);
253	    // The guest never readies: it forfeits at the ready check, and the host has five seconds to choose.
254	    await until(() => lastDuel(host)?.phase === "choosing", 8000, "the choice window");
255	    const deadline = lastDuel(host)!.choiceDeadline!;
256	    await until(() => lastDuel(host)?.phase === "settled", 8000, "the default");
257	    expect(lastDuel(host)!.settlement).toMatchObject({ tick: deadline, choice: "default", stolenType: "moon", gold: 10 });
258	    await host.waitFor(() => host.rubbings().join(",") === "sun,moon");
259	    // The choice window outlasted the (shortened) respawn wait, so the loser respawns on the settlement tick.
260	    await guest.waitFor(() => guest.status()?.protection === "respawn");
261	    expect(guest.objectives()).toMatchObject({ rubbings: [], gold: 40, settledRole: "loser", stolen: "moon" });
262	  }, 30_000);
263	
264	  it("moves only the gold when the loser holds nothing the winner lacks, and settles at once; collecting then ends the winner's protection", async ({ onTestFinished }) => {
265	    const track = tracker(onTestFinished);
266	    const { host, guest } = await pair(endpoint, track, { autoReady: false });
267	    await Promise.all([collectAt(host, endpoint, dockFor("sun"), "sun"), collectAt(guest, endpoint, dockFor("sun", 1), "sun")]);
268	    await placePair(endpoint, host, guest);
269	    await grapple(host, guest);
270	    await until(() => lastDuel(host)?.result !== null, 8000, "the forfeit");
271	    const duel = lastDuel(host)!;
272	    // A ready-check forfeit settles on its own tick when nothing is eligible: no choice window, gold only.
273	    expect(duel.phase).toBe("settled");
274	    expect(duel.settlement).toMatchObject({ tick: duel.result!.tick, choice: "none", stolenRubbingId: null, gold: 10 });
275	    await host.waitFor(() => host.gold() === 60 && host.status()?.protection === "win");
276	    expect(host.objectives()!.theftOptions).toEqual([]);
277	    expect(host.rubbings()).toEqual(["sun"]);
278	    expect(guest.rubbings()).toEqual(["sun"]);
279	    expect(guest.gold()).toBe(40);
280	
281	    // §6: starting a collection ends the winner's protection before it runs out.
282	    const { protectedUntil } = host.status()!;
283	    const moon = dockFor("moon");
284	    await host.placeShip(endpoint, { tileX: moon.tileX, tileY: moon.tileY, heading: 0 });
285	    await host.holdUntil(HOLD_E, () => host.status()?.protection === "", 3000);
286	    expect(host.worldTick).toBeLessThan(protectedUntil);
287	    expect(ledgerPlayer(host)?.channel?.kind ?? "collect").toBe("collect");
288	  }, 30_000);
289	
290	  it("moves nothing when neither fighter is ready and the duel is cancelled", async ({ onTestFinished }) => {
291	    const track = tracker(onTestFinished);
292	    const [host, guest] = (await playersAt(endpoint, [HOST_SEAT, GUEST_SEAT], track, { clients: [{ autoReady: false }, { autoReady: false }] })) as [HeadlessClient, HeadlessClient];
293	    await Promise.all([collectAt(host, endpoint, dockFor("sun"), "sun"), collectAt(guest, endpoint, dockFor("moon"), "moon")]);
294	    await placePair(endpoint, host, guest);
295	    await grapple(host, guest);
296	    await until(() => lastDuel(host)?.phase === "settled", 8000, "the cancellation");
297	    expect(lastDuel(host)).toMatchObject({ result: { outcome: "cancelled" }, settlement: { choice: "none", gold: 0 } });
298	    for (const client of [host, guest]) await client.waitFor(() => client.status()?.protection === "draw");
299	    expect(host.objectives()).toMatchObject({ rubbings: ["sun"], gold: 50, settledRole: "draw" });
300	    expect(guest.objectives()).toMatchObject({ rubbings: ["moon"], gold: 50, settledRole: "draw" });
301	  }, 30_000);
302	
303	  it("suppresses the gold of a second win over the same opponent within three minutes, but not the theft", async ({ onTestFinished }) => {
304	    const track = tracker(onTestFinished);
305	    const { host, guest } = await pair(endpoint, track, { autoReady: false });
306	    await collectAt(guest, endpoint, dockFor("sun"), "sun");
307	    await collectAt(guest, endpoint, dockFor("moon"), "moon");
308	    // First win: the host takes the Sun and 10 gold.
309	    await placePair(endpoint, host, guest);
310	    await grapple(host, guest);
311	    await host.waitFor(() => (host.objectives()?.theftOptions.length ?? 0) === 2, 8000);
312	    host.chooseTheft("sun");
313	    await host.waitFor(() => host.rubbings().join(",") === "sun" && host.gold() === 60, 2000);
314	    // The guest respawns and its protection runs out; they meet again.
315	    await guest.waitFor(() => guest.status()?.mode === "sea" && guest.status()?.protection === "", 12_000);
316	    await placePair(endpoint, host, guest);
317	    await grapple(host, guest);
318	    await host.waitFor(() => host.objectives()?.theftOptions.join(",") === "moon", 8000);
319	    host.chooseTheft("moon");
320	    await host.waitFor(() => host.rubbings().join(",") === "sun,moon", 2000);
321	    const second = lastDuel(host)!;
322	    expect(second.result!.tick - ledgerOf(host).duels[0]!.result!.tick).toBeLessThan(objectiveRules.repeatWinWindowTicks);
323	    expect(second.settlement).toMatchObject({ stolenType: "moon", gold: 0, goldSuppressed: true });
324	    expect(host.gold()).toBe(60);
325	    await guest.waitFor(() => guest.objectives()!.settledAt === second.settlement!.tick);
326	    expect(guest.objectives()).toMatchObject({ gold: 40, rubbings: [], goldChange: 0, stolen: "moon" });
327	  }, 45_000);
328	
329	
330	});
331	
332	describe.concurrent("recovery caches (§12)", () => {
333	  it("lets a player missing a type claim it from a cache in the claim time, which ends protection, and the empty cache disappears", async ({ onTestFinished }) => {
334	    const track = tracker(onTestFinished);
335	    const { host, guest } = await pair(endpoint, track, { autoReady: false });
336	    const west = dockFor("sun");
337	    // A third player carries a Moon to Palm Key's west dock and quits there: a cache with the Moon at that dock.
338	    const quitter = await HeadlessClient.join(endpoint, host.code);
339	    track(quitter);
340	    await collectAt(quitter, endpoint, dockFor("moon"), "moon");
341	    await quitter.placeShip(endpoint, { tileX: west.tileX, tileY: west.tileY, heading: 0 });
342	    await quitter.leave();
343	    await until(() => ledgerOf(host).caches.length === 1, 3000, "the cache");
344	    expect(ledgerOf(host).caches[0]).toMatchObject(dockCentre(seaMap, west.id));
345	    // The host holds a Sun (so Palm Key has nothing for it) and wins a duel: protected.
346	    await collectAt(host, endpoint, dockFor("sun", 1), "sun");
347	    await placePair(endpoint, host, guest);
348	    await grapple(host, guest);
349	    await host.waitFor(() => host.status()?.protection === "win", 8000);
350	    const { protectedUntil } = host.status()!;
351	    // Moored at the cache's dock: it sees the Moon there; E claims it, which ends the protection at once.
352	    await host.placeShip(endpoint, { tileX: west.tileX, tileY: west.tileY, heading: 0 });
353	    let claimStart = -1;
354	    await host.holdUntil(
355	      HOLD_E,
356	      () => {
357	        const channel = ledgerPlayer(host)?.channel;
358	        if (channel?.kind === "claim") claimStart = channel.startTick;
359	        return host.rubbings().includes("moon");
360	      },
361	      10_000,
362	    );
363	    expect(host.objectives()).toMatchObject({ channelResult: "claimed:moon", rubbings: ["sun", "moon"] });
364	    expect(host.objectives()!.channelResultAt - claimStart).toBe(objectiveRules.cacheClaimTicks);
365	    expect(host.status()!.protection).toBe("");
366	    expect(claimStart).toBeLessThan(protectedUntil);
367	    // Empty, the cache is gone from the ledger and from every view.
368	    expect(ledgerOf(host).caches).toEqual([]);
369	    await host.waitFor(() => host.caches().length === 0 && host.objectives()!.cacheTypes.length === 0);
370	  }, 45_000);
371	});
