1	import { matchMaker } from "colyseus";
2	import { expect } from "vitest";
3	import { isNavigable, seaMap } from "@pirate-sea-race/content";
4	import type { MatchRoom } from "@pirate-sea-race/server";
5	import { defaultSimulationConfig, hullPathIsClear, tileCentre } from "@pirate-sea-race/simulation";
6	import { duelInput } from "@pirate-sea-race/simulation/duel";
7	import { Buttons } from "@pirate-sea-race/protocol";
8	import { HeadlessClient, sleep, type DuelScript, type HeadlessClientOptions, type Movement } from "@pirate-sea-race/test-tools";
9	
10	/**
11	 * What the duel-at-sea tests share: the open stretch of sea they sail on, a pair of players placed on it, and the
12	 * scripted fighters. Each test file starts its own server; tests in a file run at once, one match each.
13	 */
14	
15	/** The row three tiles south of the hub, which the map keeps clear for a hull 20 tiles either side of the hub. */
16	export const OPEN_ROW = seaMap.hub.tileY + 3;
17	export const HUB_X = seaMap.hub.tileX;
18	export const TILE = seaMap.subUnitsPerTile;
19	/** Headings of 64: east, south, west, north. */
20	export const EAST = 0;
21	export const SOUTH = 16;
22	export const WEST = 32;
23	export const NORTH = 48;
24	
25	/**
26	 * Collects a test's clients and has them leave when that test finishes (tests in a file run at once). When it
27	 * finishes, and again once every client has left, it checks each match room those clients were in: the room checked
28	 * `checkLedger` and its own invariant (no ship removed while the ledger counts its player in the match, and no ship
29	 * without such a player) after every world tick, and found no violation; and the ledger refused nothing the room asked.
30	 */
31	export function tracker(onTestFinished: (fn: () => Promise<void>) => void): (client: HeadlessClient) => void {
32	  const clients: HeadlessClient[] = [];
33	  const rooms = new Set<MatchRoom>();
34	  onTestFinished(async () => {
35	    const checked = [...rooms];
36	    await Promise.all(clients.map((client) => client.leave()));
37	    await sleep(150);
38	    for (const room of checked) {
39	      expect(room.invariantViolations, `invariants of match ${room.state.code}`).toEqual([]);
40	      expect(room.ledgerRefusals, `ledger refusals in match ${room.state.code}`).toEqual([]);
41	    }
42	  });
43	  return (client) => {
44	    clients.push(client);
45	    const room = roomOf(client);
46	    if (room !== undefined) rooms.add(room);
47	  };
48	}
49	
50	/**
51	 * The test source layout (the server's test-only setting): Palm Key (island 0) and Old Stones (2) seal two Suns each,
52	 * Ember Rock (1) and Mist Cay (3) two Moons each, so a test picks a type by the island it moors at.
53	 */
54	export const TEST_SOURCE_LAYOUT = [
55	  ["sun", "sun"],
56	  ["moon", "moon"],
57	  ["sun", "sun"],
58	  ["moon", "moon"],
59	] as const;
60	
61	/** A dock of the island that seals `type` in the test layout: Palm Key's west dock for Sun, Ember Rock's east for Moon. */
62	export function dockFor(type: "sun" | "moon", which = 0): (typeof seaMap.docks)[number] {
63	  const islands = TEST_SOURCE_LAYOUT.flatMap((types, island) => (types[0] === type ? [island] : []));
64	  return seaMap.docks.filter((dock) => islands.includes(dock.island))[which]!;
65	}
66	
67	/** Holding E with no throttle: moors at a dock in reach, and keeps holding to collect or claim there. */
68	export const HOLD_E: Movement = { moveX: 0, moveY: 0, buttons: Buttons.Interact };
69	
70	/**
71	 * Puts a client's ship on a dock's tile, moors it there and holds E until it holds `type` (a collection, or a claim
72	 * from a cache there), then lets go.
73	 */
74	export async function collectAt(client: HeadlessClient, endpoint: string, dock: { id: number; tileX: number; tileY: number }, type: string, timeoutMs = 15_000): Promise<void> {
75	  await client.placeShip(endpoint, { tileX: dock.tileX, tileY: dock.tileY, heading: 0 });
76	  await client.holdUntil(HOLD_E, () => client.rubbings().includes(type), timeoutMs);
77	  expect(client.ship()?.dock).toBe(dock.id);
78	}
79	
80	export function roomOf(client: HeadlessClient): MatchRoom {
81	  return matchMaker.getLocalRoomById(client.room.roomId) as unknown as MatchRoom;
82	}
83	
84	/** Resolves once `predicate` holds for the room itself (its ledger or rules state), polling; rejects after `timeoutMs`. */
85	export async function until(predicate: () => boolean, timeoutMs = 5000, what = "condition"): Promise<void> {
86	  const deadline = Date.now() + timeoutMs;
87	  while (!predicate()) {
88	    if (Date.now() > deadline) throw new Error(`${what} not met within ${timeoutMs} ms`);
89	    await sleep(10);
90	  }
91	}
92	
93	export interface Seat {
94	  readonly tileX: number;
95	  readonly tileY: number;
96	  readonly heading: number;
97	}
98	
99	/** Whether a hull can sail the straight line between two tile centres (and so the tiles between see each other). */
100	export function openWater(from: Seat, to: Seat): boolean {
101	  const a = tileCentre(defaultSimulationConfig, from.tileX, from.tileY);
102	  const b = tileCentre(defaultSimulationConfig, to.tileX, to.tileY);
103	  return isNavigable(seaMap, from.tileX, from.tileY) && hullPathIsClear(defaultSimulationConfig, a.x, a.y, b.x, b.y);
104	}
105	
106	/** Players in one match, created in order (the first creates it), then placed at rest on their seats. */
107	export async function playersAt(
108	  endpoint: string,
109	  seats: readonly Seat[],
110	  track: (client: HeadlessClient) => void,
111	  options: { readonly endpoints?: readonly string[]; readonly clients?: readonly HeadlessClientOptions[] } = {},
112	): Promise<HeadlessClient[]> {
113	  const clients: HeadlessClient[] = [];
114	  for (const [index, seat] of seats.entries()) {
115	    const via = options.endpoints?.[index] ?? endpoint;
116	    const client = index === 0 ? await HeadlessClient.create(via, options.clients?.[0]) : await HeadlessClient.join(via, clients[0]!.code, options.clients?.[index]);
117	    track(client);
118	    clients.push(client);
119	    expect(openWater(seat, seat)).toBe(true);
120	  }
121	  await clients[0]!.waitFor(() => clients[0]!.playerCount === seats.length);
122	  for (const [index, seat] of seats.entries()) await clients[index]!.placeShip(endpoint, seat);
123	  return clients;
124	}
125	
126	/**
127	 * The host (attacker) and the guest in grapple range on the open row, `apart` tiles apart around the hub: the host
128	 * west facing east, the guest east facing `guestHeading` (west by default, toward the host).
129	 */
130	export async function pairInRange(
131	  endpoint: string,
132	  track: (client: HeadlessClient) => void,
133	  options: {
134	    readonly apart?: number;
135	    readonly guestHeading?: number;
136	    readonly endpoints?: readonly string[];
137	    readonly clients?: readonly HeadlessClientOptions[];
138	  } = {},
139	): Promise<{ host: HeadlessClient; guest: HeadlessClient }> {
140	  const apart = options.apart ?? 6;
141	  const host: Seat = { tileX: HUB_X - Math.floor(apart / 2), tileY: OPEN_ROW, heading: EAST };
142	  const guest: Seat = { tileX: host.tileX + apart, tileY: OPEN_ROW, heading: options.guestHeading ?? WEST };
143	  expect(openWater(host, guest)).toBe(true);
144	  const [first, second] = await playersAt(endpoint, [host, guest], track, options);
145	  await first!.waitFor(() => first!.ship(second!.sessionId) !== undefined);
146	  return { host: first!, guest: second! };
147	}
148	
149	/** Grapples: the host taps J, and both fighters' duel reaches its countdown. */
150	export async function grapple(host: HeadlessClient, guest: HeadlessClient): Promise<void> {
151	  host.tapGrapple();
152	  for (const client of [host, guest]) await client.waitFor(() => client.fighter.phase === "countdown", 3000);
153	}
154	
155	const R = duelInput("right");
156	const L = duelInput("left");
157	const K = duelInput("heavy");
158	
159	/**
160	 * A fighter who walks in, then swings a heavy every 50 frames and steps forward before each: from either side, the
161	 * mirror of the other side's (player one starts on the left). Against a fighter who stands still it wins by KO in
162	 * about 500 frames; played by both, the mirrored fight ends in a double KO.
163	 */
164	export function brawler(slot: 0 | 1): DuelScript {
165	  const toward = slot === 0 ? R : L;
166	  return (frame) => {
167	    if (frame < 30) return toward;
168	    const beat = (frame - 30) % 50;
169	    if (beat === 0) return K;
170	    return beat > 44 ? toward : 0;
171	  };
172	}
173	
174	/** The lobby a fighter sees, as plain values. */
175	export function lobbyOf(client: HeadlessClient): { phase: string; winner: number; reason: string } | undefined {
176	  const lobby = client.fighter.lobby;
177	  return lobby === undefined ? undefined : { phase: lobby.phase, winner: lobby.winner, reason: lobby.reason };
178	}
179	
180	/** The fighters' result, once both see it (the same in both). */
181	export async function resultOf(host: HeadlessClient, guest: HeadlessClient, timeoutMs = 20_000): Promise<{ phase: string; winner: number; reason: string }> {
182	  for (const client of [host, guest]) await client.waitFor(() => client.fighter.phase === "over", timeoutMs);
183	  expect(lobbyOf(guest)).toEqual(lobbyOf(host));
184	  return lobbyOf(host)!;
185	}
186	
187	/** Every grapple and marker a client decoded from now on, as the patches arrive. */
188	export function recordSightings(client: HeadlessClient): { grapples: Set<string>; markers: number; duelLobbies: number } {
189	  const seen = { grapples: new Set<string>(), markers: 0, duelLobbies: 0 };
190	  client.room.onStateChange(() => {
191	    for (const grapple of client.grapples()) seen.grapples.add(`${grapple.attackerId}>${grapple.defenderId}`);
192	    seen.markers = Math.max(seen.markers, client.markers().length);
193	    seen.duelLobbies = Math.max(seen.duelLobbies, client.duelCount);
194	  });
195	  return seen;
196	}
197	
198	export function containsText(frame: Uint8Array, text: string): boolean {
199	  return Buffer.from(frame).includes(Buffer.from(text, "utf8"));
200	}
201

