2658	+import { z } from "zod";
2659	+import { encodedSize } from "./input.js";
2660	+
2661	+/**
2662	+ * The rubbing messages (protocol v6, §4 and §16). Collecting at a source and claiming from a recovery cache need no
2663	+ * message of their own: the player holds interact (E) moored at the dock, and the server decides the target. The one
2664	+ * new client message is the theft choice.
2665	+ */
2666	+export const RubbingMessageType = {
2667	+  /** Client → server: the winner of a duel picks the rubbing type to steal (`ChooseTheftMessage`). */
2668	+  ChooseTheft: "choose-theft",
2669	+} as const;
2670	+
2671	+/**
2672	+ * The four rubbing types in the fixed type order (content's `RUBBING_TYPES`, which the protocol does not depend on).
2673	+ * A server unit test keeps the two equal.
2674	+ */
2675	+export const RUBBING_TYPE_NAMES = ["sun", "moon", "tide", "storm"] as const;
2676	+
2677	+/** The largest theft choice accepted, measured as its JSON encoding. A valid one is under 40 bytes. */
2678	+export const MAX_CHOOSE_THEFT_BYTES = 64;
2679	+/** Theft choices a client may send per second before the server drops the rest. */
2680	+export const MAX_CHOOSE_THEFT_PER_SECOND = 8;
2681	+
2682	+/**
2683	+ * §16: a theft choice refers to a server-created duel result (`duel`, the opaque key of the winner's own duel lobby)
2684	+ * and names one type. It is not a transfer request: the server checks that the sender won that duel, that its choice
2685	+ * window is open and that the type is eligible, and otherwise changes nothing.
2686	+ */
2687	+export const chooseTheftMessageSchema = z.strictObject({
2688	+  duel: z.string().min(1).max(16),
2689	+  type: z.enum(RUBBING_TYPE_NAMES),
2690	+});
2691	+
2692	+export type ChooseTheftMessage = z.infer<typeof chooseTheftMessageSchema>;
2693	+
2694	+/** Validates an untrusted theft choice: its size, then its schema. */
2695	+export function validateChooseTheftMessage(message: unknown): ChooseTheftMessage | undefined {
2696	+  const size = encodedSize(message);
2697	+  if (size === undefined || size > MAX_CHOOSE_THEFT_BYTES) return undefined;
2698	+  const parsed = chooseTheftMessageSchema.safeParse(message);
2699	+  return parsed.success ? parsed.data : undefined;
2700	+}
